llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed only 0.17% systemic availability in humans after oral ingestion, providing affirmative evidence that large, non-ionizable isoprenoid lipids are poorly absorbed; this supports low F for the similarly lipophilic ubiquinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich palm oil, whose components have a polar chromanol head and long isoprenoid tail analogous to CoQ10, exhibits poor oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "8-Prenylnaringenin, a prenylated lipophilic polyphenol, has low oral bioavailability in humans, supporting the expectation that highly lipophilic prenylated/quinonoid molecules are poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "BI 425809, a small drug-like molecule, had 71.6% absolute bioavailability in humans; this is contradictory to low F but has limited structural transfer to the query's extreme molecular weight and lipophilicity.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Finerenone, a small drug-like molecule, had 43.5% absolute bioavailability in humans; contradictory to low F but not representative of the query's physicochemical class.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Phytoene, a C40 isoprenoid, showed 58% bioavailability in humans, and cis-lycopene reached 24.5%; these structurally related high values are contradictory, but they are outweighed by the predominantly low systemic availability of lycopene and the query's larger, more lipophilic ubiquinone structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a prenylated lipophilic natural product, showed high oral bioavailability in volunteers; contradictory to low F, but its smaller size and extract formulation limit transfer to CoQ10.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is CoQ10, an extremely lipophilic, high-molecular-weight ubiquinone with a long isoprenoid tail and no ionizable groups. Although several small drug-like molecules with high transfer scores show high oral bioavailability, they are not structurally representative. The most relevant lipophilic isoprenoid evidence is mixed: lycopene and tocotrienols show low systemic availability, while phytoene and cis-lycopene show higher values. Given the query's very high MW, extreme logP, lack of ionizable groups, and affirmative low-absorption evidence from analogous isoprenoid lipids, F is more likely below 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for CoQ10 itself in humans.",
    "Lycopene and tocotrienol evidence has low assay-transfer scores, reducing weight.",
    "High-F small-molecule evidence is not structurally transferable to the query.",
    "Formulation effects that might improve absorption are not captured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

